cat > /tmp/mock-empty.mjs << 'EOF'
import http from 'node:http';
function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
  res.end(JSON.stringify(body));
}
const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'OPTIONS') {
    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*', 'Access-Control-Allow-Methods': '*' });
    return res.end();
  }
  if (url.pathname === '/api/v1/contracts') return send(res, 200, { items: [], totalCount: 0 });
  if (url.pathname === '/api/v1/folder-tags') return send(res, 200, []);
  send(res, 404, { error: 'Not found', details: [] });
});
server.listen(5198, () => console.log('empty mock on :5198'));
EOF
